package br.com.sussmartcare.presence.domain; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="presence_events") public class PresenceEvent { @Id private UUID id; @Column(nullable=false) private UUID visitId; @Column(nullable=false) private UUID patientId; @Column(nullable=false) private String eventType; private String zoneId; @Column(nullable=false) private String source; @Column(nullable=false) private Instant occurredAt; protected PresenceEvent(){} public PresenceEvent(UUID visit,UUID patient,String type,String zone,String source,Instant at){id=UUID.randomUUID();visitId=visit;patientId=patient;eventType=type;zoneId=zone;this.source=source;occurredAt=at==null?Instant.now():at;} public UUID getId(){return id;} public UUID getVisitId(){return visitId;} public UUID getPatientId(){return patientId;} public String getEventType(){return eventType;} public String getZoneId(){return zoneId;} public String getSource(){return source;} public Instant getOccurredAt(){return occurredAt;} }